<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'; import { ElMessage } from 'element-plus'; import { Lock, Refresh } from '@element-plus/icons-vue'; import { authApi } from '@/api/auth'; import { enterpriseApi } from '@/api/enterprise'; import type { EnterpriseInfo } from '@/types/domain'; import PageHeader from '@/components/PageHeader.vue'; import { useAsyncAction } from '@/composables/useAsyncAction'
const profile = ref<EnterpriseInfo>(); const loading = ref(false); const passwordVisible = ref(false); const password = reactive({ oldPassword: '', newPassword: '', confirmPassword: '' }); const { loading: actionLoading, run } = useAsyncAction()
async function load() { loading.value = true; try { profile.value = await enterpriseApi.profile() } finally { loading.value = false } }
async function changePassword() { if (!password.oldPassword || password.newPassword.length < 6 || password.newPassword !== password.confirmPassword) return ElMessage.warning('请检查密码填写，长度至少 6 位且两次一致'); await run(() => authApi.enterprisePassword(password), '密码已修改，请重新登录'); passwordVisible.value = false; Object.assign(password, { oldPassword: '', newPassword: '', confirmPassword: '' }) }
onMounted(load)
</script>
<template><div class="profile-view"><PageHeader eyebrow="ENTERPRISE PROFILE" title="企业资料" description="查看本企业在冷链网络中的注册信息"><template #default><el-button :icon="Refresh" @click="load">刷新资料</el-button></template></PageHeader><div class="profile-grid" v-loading="loading"><section class="data-panel profile-card"><div class="profile-card__hero"><span class="profile-card__avatar">{{ profile?.enterpriseName?.slice(0, 1) || '企' }}</span><div><h2>{{ profile?.enterpriseName || '加载中' }}</h2><p>{{ profile?.enterpriseTypeName || '-' }} · {{ profile?.enterpriseCode || '-' }}</p></div><el-tag type="success">已接入</el-tag></div><div class="detail-list detail-list--grid"><div><span>统一信用代码</span><strong>{{ profile?.creditCode || '-' }}</strong></div><div><span>登录账号</span><strong>{{ profile?.loginName || '-' }}</strong></div><div><span>法定代表人</span><strong>{{ profile?.legalPerson || '-' }}</strong></div><div><span>联系人</span><strong>{{ profile?.contactPerson || '-' }} {{ profile?.contactPhone || '' }}</strong></div><div><span>所在地区</span><strong>{{ profile?.provinceName }} · {{ profile?.cityName }}</strong></div><div><span>注册地址</span><strong>{{ profile?.address || '-' }}</strong></div></div></section><section class="data-panel profile-security"><div class="data-panel__head"><div><strong>账户安全</strong><span>定期修改密码，保护企业账号</span></div></div><div class="security-row"><span class="security-row__icon"><el-icon><Lock /></el-icon></span><div><strong>登录密码</strong><p>上次修改后持续保护中</p></div><el-button plain @click="passwordVisible = true">修改密码</el-button></div></section></div><el-dialog v-model="passwordVisible" title="修改登录密码" width="430px"><el-form label-position="top"><el-form-item label="当前密码"><el-input v-model="password.oldPassword" type="password" show-password /></el-form-item><el-form-item label="新密码"><el-input v-model="password.newPassword" type="password" show-password /></el-form-item><el-form-item label="确认新密码"><el-input v-model="password.confirmPassword" type="password" show-password /></el-form-item></el-form><template #footer><el-button @click="passwordVisible = false">取消</el-button><el-button type="primary" :loading="actionLoading" @click="changePassword">确认修改</el-button></template></el-dialog></div></template>
